package com.laptopshop.controller; import com.laptopshop.dto.*; import com.laptopshop.entity.*; import com.laptopshop.exception.*; import com.laptopshop.service.*; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller @RequestMapping("/admin/categories") public class CategoryController { private final CategoryService service; public CategoryController(CategoryService s){service=s;}
 @GetMapping public String list(@RequestParam(defaultValue="") String keyword,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(defaultValue="name") String sortBy,@RequestParam(defaultValue="asc") String direction,Model m){var p=service.getCategories(keyword,page,size,sortBy,direction);m.addAttribute("categoryPage",p);m.addAttribute("keyword",keyword);m.addAttribute("sortBy",sortBy);m.addAttribute("direction",direction);return "categories/list";}
 @GetMapping("/add") public String add(Model m){m.addAttribute("categoryDTO",new CategoryDTO());m.addAttribute("isEdit",false);return "categories/form";}
 @PostMapping("/add") public String create(@Valid @ModelAttribute CategoryDTO categoryDTO,BindingResult br,Model m,RedirectAttributes ra){if(br.hasErrors()){m.addAttribute("isEdit",false);return "categories/form";}try{service.createCategory(categoryDTO);ra.addFlashAttribute("successMessage","Thêm danh mục thành công");return "redirect:/admin/categories";}catch(BusinessException e){m.addAttribute("errorMessage",e.getMessage());m.addAttribute("isEdit",false);return "categories/form";}}
 @GetMapping("/edit/{id}") public String edit(@PathVariable Integer id,Model m,RedirectAttributes ra){try{Category c=service.getCategoryById(id);CategoryDTO d=new CategoryDTO();d.setId(c.getId());d.setName(c.getName());d.setDescription(c.getDescription());d.setIsActive(c.getIsActive());m.addAttribute("categoryDTO",d);m.addAttribute("isEdit",true);return "categories/form";}catch(ResourceNotFoundException e){ra.addFlashAttribute("errorMessage",e.getMessage());return "redirect:/admin/categories";}}
 @PostMapping("/edit/{id}") public String update(@PathVariable Integer id,@Valid @ModelAttribute CategoryDTO categoryDTO,BindingResult br,Model m,RedirectAttributes ra){if(br.hasErrors()){m.addAttribute("isEdit",true);return "categories/form";}try{service.updateCategory(id,categoryDTO);ra.addFlashAttribute("successMessage","Cập nhật danh mục thành công");return "redirect:/admin/categories";}catch(RuntimeException e){m.addAttribute("errorMessage",e.getMessage());m.addAttribute("isEdit",true);return "categories/form";}}
 @PostMapping("/delete/{id}") public String delete(@PathVariable Integer id,RedirectAttributes ra){try{service.deleteCategory(id);ra.addFlashAttribute("successMessage","Xóa danh mục thành công");}catch(RuntimeException e){ra.addFlashAttribute("errorMessage",e.getMessage());}return "redirect:/admin/categories";}}
